"use strict";(()=>{const root=document.getElementById('tracingQuizRoot');if(!root)return;const letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');for(let i=letters.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[letters[i],letters[j]]=[letters[j],letters[i]]}let step=0;const results=Array(10).fill(null);const drawings=Array(10).fill(null);const say=message=>{try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.lang='en-IN';u.rate=.83;speechSynthesis.speak(u)}catch{}};function finish(){const score=results.filter(x=>x===true).length;root.innerHTML='<section class="practice-box"><h2>Letter Tracing Quiz complete</h2><p class="game-question">'+score+' / 10</p><p>Your grown-up reviewed your handwriting.</p><div id="sharedScoreCard"></div><button class="practice-button" id="againTracing">Try again</button><a class="practice-button" href="letter-tracing.html">← Letter tracing practice</a></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:10,title:'Letter Tracing Quiz',subtitle:'Parent-guided handwriting practice',filename:'learnwithus-tracing-score.svg',url:'letter-tracing-quiz.html'});window.LearnWithUs?.recordQuiz?.('Letter Tracing Quiz',score,10,'letter-tracing-quiz.html');document.getElementById('againTracing').onclick=()=>location.reload()}function round(){if(step===10)return finish();const letter=letters[step];root.innerHTML='<section class="practice-box"><p class="game-progress">Letter '+(step+1)+' of 10</p><h2>Trace the letter '+letter+'</h2><p>Follow the pale letter with a finger, stylus or mouse. A grown-up reviews the handwriting.</p><div class="trace-board"><span class="trace-template">'+letter+'</span><canvas class="trace-canvas" id="traceQuizCanvas" width="540" height="300" aria-label="Write letter '+letter+'"></canvas></div><div class="trace-hear-row"><button class="practice-button" id="hearTraceQuiz">🔊 Hear '+letter+'</button><button class="practice-button" id="clearTraceQuiz">Clear</button></div><p class="game-feedback" id="traceResult" role="status"></p><div class="trace-controls"><button class="practice-button" id="traceCorrect">✓ Written correctly</button><button class="practice-button" id="traceRetry">↻ Needs practice</button></div><nav class="trace-step-nav" aria-label="Tracing question navigation"><button type="button" class="practice-button" id="prevTraceQuiz" '+(step===0?'disabled':'')+'>← Previous letter</button><button type="button" class="practice-button game-next" id="nextTraceQuiz">'+(step===9?'See score →':'Next letter →')+'</button></nav></section>';const canvas=document.getElementById('traceQuizCanvas'),ctx=canvas.getContext('2d');ctx.strokeStyle='#237a57';ctx.lineWidth=11;ctx.lineCap='round';ctx.lineJoin='round';let drawing=false,marked=!!drawings[step];if(drawings[step]){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0);img.src=drawings[step]}function save(){try{drawings[step]=canvas.toDataURL()}catch{}}const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture?.(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));ctx.lineTo(...point(e));ctx.stroke();marked=true;save()};canvas.onpointermove=e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke();marked=true;save()};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;save()};document.getElementById('clearTraceQuiz').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);marked=false;drawings[step]=null;results[step]=null;status()};document.getElementById('hearTraceQuiz').onclick=()=>say('Trace '+letter);const feedback=document.getElementById('traceResult');function status(){feedback.textContent=results[step]===true?'Correctly written! Well done.':results[step]===false?'Needs practice. Trace '+letter+' again.':''}status();function evaluate(ok){if(!marked){feedback.textContent='Trace the letter before your grown-up checks it.';return}results[step]=ok;const msg=ok?'Correctly written! Well done.':'Needs practice. Let us try writing '+letter+' again.';feedback.textContent=msg;say(msg)}document.getElementById('traceCorrect').onclick=()=>evaluate(true);document.getElementById('traceRetry').onclick=()=>evaluate(false);document.getElementById('prevTraceQuiz').onclick=()=>{save();if(step>0){step--;round()}};document.getElementById('nextTraceQuiz').onclick=()=>{if(results[step]===null){feedback.textContent='Ask a grown-up to mark this letter before continuing.';return}save();step++;round()}}round()})();